cd ~/Documents/git/krt-gpm
# imx6ulz_4l full route (plan-pcb-routing, followed by hand). 4-layer STANDARD tier: GND solid on In1 (price 6.0),
# +3V3 split with VMEM on In2 (price 2.5), F/B signal layers. Board floors held everywhere (--escalation board):
# via 0.45/0.25, track 0.1, clearance 0.1, hole-to-hole 0.25 and edge 0.3 read from the board.
export REDO_RUNDIR=wk/gpm/14_imx6ulz_4l/final_route
export REDO_MANIFEST=wk/gpm/14_imx6ulz_4l/final_route/redo_commands.sh
export KICAD_ROUTE_TRACE=1
python3 -X utf8 py_router/copy_board.py wk/gpm/14_imx6ulz_4l/final.kicad_pcb wk/gpm/14_imx6ulz_4l/final_route/in.kicad_pcb
# Step 1: the bare pour, before fanout
python3 -X utf8 py_router/route_planes.py wk/gpm/14_imx6ulz_4l/final_route/in.kicad_pcb wk/gpm/14_imx6ulz_4l/final_route/s1_planes.kicad_pcb --nets GND +3V3 VMEM --plane-layers In1.Cu In2.Cu In2.Cu --clearance-ceiling 0.1 > wk/gpm/14_imx6ulz_4l/final_route/s1_planes.log 2>&1
# Step 1b: dog-bone fanout of both 0.8 mm BGAs, plane nets excluded (they get plane-drop vias); In1 (solid GND) and In2 (split +3V3/VMEM) forbidden (rule R17)
python3 -X utf8 py_router/bga_fanout.py wk/gpm/14_imx6ulz_4l/final_route/s1_planes.kicad_pcb --output wk/gpm/14_imx6ulz_4l/final_route/s2_fanU1.kicad_pcb --component U1 --nets '*' '!GND' '!+3V3' '!VMEM' --layers F.Cu In1.Cu In2.Cu B.Cu --layer-costs 1.0 -1 2.5 1.0 --escape-method dogbone --via-size 0.45 --via-drill 0.25 --track-width 0.1 --clearance-ceiling 0.1 --escalation board > wk/gpm/14_imx6ulz_4l/final_route/s2_fanU1.log 2>&1
python3 -X utf8 py_router/bga_fanout.py wk/gpm/14_imx6ulz_4l/final_route/s2_fanU1.kicad_pcb --output wk/gpm/14_imx6ulz_4l/final_route/s3_fanU2.kicad_pcb --component U2 --nets '*' '!GND' '!+3V3' '!VMEM' --layers F.Cu In1.Cu In2.Cu B.Cu --layer-costs 1.0 -1 2.5 1.0 --escape-method dogbone --via-size 0.45 --via-drill 0.25 --track-width 0.1 --clearance-ceiling 0.1 --escalation board > wk/gpm/14_imx6ulz_4l/final_route/s3_fanU2.log 2>&1
# Step 1c: ONE cap pass after the last fanout, holding the intent's decap limits
python3 -X utf8 py_placer/place_fanout_clearance.py wk/gpm/14_imx6ulz_4l/final_route/s3_fanU2.kicad_pcb wk/gpm/14_imx6ulz_4l/final_route/s4_caps.kicad_pcb --clearance 0.1 --intent wk/gpm/14_imx6ulz_4l/intent_run.json > wk/gpm/14_imx6ulz_4l/final_route/s4_caps.log 2>&1
# Step 2a: the three DDR3 pairs (fab-floor gap = clearance), same layer costs as the route step
python3 -X utf8 py_router/route_diff.py wk/gpm/14_imx6ulz_4l/final_route/s4_caps.kicad_pcb wk/gpm/14_imx6ulz_4l/final_route/s5_diff.kicad_pcb --nets '/DRAM/DRAM_CLK0_*' '/DRAM/DRAM_DQS*' --track-width 0.1 --diff-pair-gap 0.1 --clearance-ceiling 0.1 --layers F.Cu In1.Cu In2.Cu B.Cu --layer-costs 1.0 6.0 2.5 1.0 --via-size 0.45 --via-drill 0.25 --escalation board --json-out wk/gpm/14_imx6ulz_4l/final_route/s5_diff.json > wk/gpm/14_imx6ulz_4l/final_route/s5_diff.log 2>&1
# Step 2: every net, plane nets included (in-run plane finalize), then two Step 2d iterations with the same flags
python3 -X utf8 py_router/route.py wk/gpm/14_imx6ulz_4l/final_route/s5_diff.kicad_pcb wk/gpm/14_imx6ulz_4l/final_route/s6_route.kicad_pcb --nets '*' --layers F.Cu In1.Cu In2.Cu B.Cu --layer-costs 1.0 6.0 2.5 1.0 --track-width 0.1 --clearance-ceiling 0.1 --via-size 0.45 --via-drill 0.25 --no-bga-zones --max-ripup 5 --escalation board --power-nets GND +3V3 VMEM +5V +1V2 '/SOC Power/V1P27_SW' '/SOC Power/V3P3_SW' '/SOC Power/VMEM_SW' '/SOC Power/VDD_ARM_SOC_IN' '/SOC Power/VDD_SOC_CAP' '/SOC Power/VDD_ARM_CAP' '/SOC Power/VDD_HIGH_IN' '/SOC Power/VDD_HIGH_CAP' '/SOC Power/VDD_SNVS_IN' --power-nets-widths 0.3 0.3 0.4 0.5 0.5 0.6 0.6 0.6 0.4 0.3 0.3 0.3 0.25 0.2 --json-out wk/gpm/14_imx6ulz_4l/final_route/s6_route.json > wk/gpm/14_imx6ulz_4l/final_route/s6_route.log 2>&1
python3 -X utf8 py_router/route.py wk/gpm/14_imx6ulz_4l/final_route/s6_route.kicad_pcb wk/gpm/14_imx6ulz_4l/final_route/s7_iter1.kicad_pcb --nets '*' --layers F.Cu In1.Cu In2.Cu B.Cu --layer-costs 1.0 6.0 2.5 1.0 --track-width 0.1 --clearance-ceiling 0.1 --via-size 0.45 --via-drill 0.25 --no-bga-zones --max-ripup 5 --escalation board --power-nets GND +3V3 VMEM +5V +1V2 '/SOC Power/V1P27_SW' '/SOC Power/V3P3_SW' '/SOC Power/VMEM_SW' '/SOC Power/VDD_ARM_SOC_IN' '/SOC Power/VDD_SOC_CAP' '/SOC Power/VDD_ARM_CAP' '/SOC Power/VDD_HIGH_IN' '/SOC Power/VDD_HIGH_CAP' '/SOC Power/VDD_SNVS_IN' --power-nets-widths 0.3 0.3 0.4 0.5 0.5 0.6 0.6 0.6 0.4 0.3 0.3 0.3 0.25 0.2 --json-out wk/gpm/14_imx6ulz_4l/final_route/s7_iter1.json > wk/gpm/14_imx6ulz_4l/final_route/s7_iter1.log 2>&1
python3 -X utf8 py_router/route.py wk/gpm/14_imx6ulz_4l/final_route/s7_iter1.kicad_pcb wk/gpm/14_imx6ulz_4l/final_route/s8_iter2.kicad_pcb --nets '*' --layers F.Cu In1.Cu In2.Cu B.Cu --layer-costs 1.0 6.0 2.5 1.0 --track-width 0.1 --clearance-ceiling 0.1 --via-size 0.45 --via-drill 0.25 --no-bga-zones --max-ripup 5 --escalation board --power-nets GND +3V3 VMEM +5V +1V2 '/SOC Power/V1P27_SW' '/SOC Power/V3P3_SW' '/SOC Power/VMEM_SW' '/SOC Power/VDD_ARM_SOC_IN' '/SOC Power/VDD_SOC_CAP' '/SOC Power/VDD_ARM_CAP' '/SOC Power/VDD_HIGH_IN' '/SOC Power/VDD_HIGH_CAP' '/SOC Power/VDD_SNVS_IN' --power-nets-widths 0.3 0.3 0.4 0.5 0.5 0.6 0.6 0.6 0.4 0.3 0.3 0.3 0.25 0.2 --json-out wk/gpm/14_imx6ulz_4l/final_route/s8_iter2.json > wk/gpm/14_imx6ulz_4l/final_route/s8_iter2.log 2>&1
